/**
 * Dharthi Tech – Krushak-Path Full-Stack Server
 * Express 4.x + Vite Middleware / Production Static Server
 */

import dotenv from 'dotenv';
dotenv.config();

import express from 'express';
import path from 'path';
import { fileURLToPath } from 'url';
import { createServer as createViteServer } from 'vite';
import { apiRouter } from './server/routes/api';

const getDirname = () => {
  if (typeof __dirname !== 'undefined') {
    return __dirname;
  }
  if (typeof import.meta !== 'undefined' && import.meta.url) {
    try {
      return path.dirname(fileURLToPath(import.meta.url));
    } catch (e) {}
  }
  return process.cwd();
};

const currentDir = getDirname();


async function startServer() {
  const app = express();
  const PORT = process.env.PORT || 3000;


  // CORS Headers for Capacitor Android app & external clients
  app.use((req, res, next) => {
    res.header('Access-Control-Allow-Origin', '*');
    res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS, PATCH');
    res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept, Authorization');
    if (req.method === 'OPTIONS') {
      return res.sendStatus(200);
    }
    next();
  });

  // JSON Body Parser with limit for plant leaf scan images
  app.use(express.json({ limit: '15mb' }));
  app.use(express.urlencoded({ extended: true, limit: '15mb' }));

  // API Health Check
  app.get('/api/health', (req, res) => {
    res.json({
      status: 'ok',
      service: 'Dharthi Tech – Krushak-Path Agritech Engine',
      time: new Date().toISOString(),
    });
  });

  // Mount REST API
  app.use('/api', apiRouter);

  // Vite middleware in development or static serving in production
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  const appUrl = process.env.APP_URL || `http://localhost:${PORT}`;
  app.listen(PORT, '0.0.0.0', () => {
    console.log(`🌾 Dharthi Tech server running on ${appUrl}`);
  });

}

startServer().catch((err) => {
  console.error('Failed to boot Krushak-Path server:', err);
  process.exit(1);
});
