const PRIMARY_MODELS = ['gemini-3.7-flash', 'gemini-flash-latest', 'gemini-3.1-flash-lite'];

async function generateWithFallback(
  ai: GoogleGenAI,
  params: Parameters<typeof ai.models.generateContent>[0]
) {
  let lastError: any = null;
  for (const model of PRIMARY_MODELS) {
    try {
      const response = await ai.models.generateContent({
        ...params,
        model,
      });
      if (response.text) {
        return response;
      }
    } catch (err: any) {
      lastError = err;
      const status = err?.status || err?.code || (err?.message?.includes('503') ? 503 : null);
      // If 503 (high demand) or 429 (rate limit) or 404, try the next model in sequence
      console.warn(`Model ${model} unavailable (${status || 'error'}), attempting next model...`);
    }
  }
  throw lastError;
}

