/**
 * Dharthi Tech – WhatsApp Diagnosis Advisory Service
 * Generates strictly localized, single-language diagnosis summaries for farmers
 * and formats compliant WhatsApp deep links or triggers WhatsApp Business API.
 */

export interface DiagnosisSharePayload {
  phone: string;
  cropName: string;
  language?: string;
  result: {
    diseaseName: string;
    causalAgent?: string;
    confidence?: number;
    severity?: string;
    description?: string;
    symptoms?: string[];
    possibleReason?: string;
    organicRemedies?: string[];
    chemicalRemedies?: string[];
    safeUsageInstructions?: string;
    precautions?: string[];
    weatherWarning?: string;
  };
}

export function generateLocalizedWhatsAppMessage(payload: DiagnosisSharePayload): string {
  const lang = (payload.language || 'en').toLowerCase();
  const crop = payload.cropName || 'Crop';
  const r: Partial<DiagnosisSharePayload['result']> = payload.result || {};
  const disease = r.diseaseName || 'Diagnosed Condition';
  const confidence = r.confidence ? `${r.confidence}%` : 'High';
  const severity = r.severity || 'Moderate';
  
  const symptomsList = (r.symptoms && r.symptoms.length > 0)
    ? r.symptoms.join(', ')
    : (r.description || 'Noted leaf and foliage abnormalities');

  const cause = r.possibleReason || r.causalAgent || 'Fungal or environmental stress';

  const organic = (r.organicRemedies && r.organicRemedies.length > 0)
    ? r.organicRemedies.join('; ')
    : 'Neem oil spray (5ml/L), application of bio-fungicides';

  const chemical = (r.chemicalRemedies && r.chemicalRemedies.length > 0)
    ? r.chemicalRemedies.join('; ')
    : 'Copper Oxychloride (3g/L) or Mancozeb as prescribed';

  const safety = r.safeUsageInstructions || 'Wear protective mask and gloves during spraying. Spray during calm morning hours.';
  
  const precautionsList = (r.precautions && r.precautions.length > 0)
    ? r.precautions.join('; ')
    : 'Avoid spraying during strong winds or direct rain. Observe waiting period before harvesting.';

  const weather = r.weatherWarning || 'Monitor local weather; avoid foliar spraying if rain is expected within 4 hours.';

  const now = new Date();
  const dateTimeStr = now.toLocaleDateString('en-IN', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
  }) + ', ' + now.toLocaleTimeString('en-IN', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: true,
  });

  if (lang === 'te') {
    return [
      `*ధర్తీ టెక్ - పంట వ్యాధి నిర్ధారణ నివేదిక*`,
      ``,
      `*పంట:* ${crop}`,
      `*గుర్తించిన సమస్య / తెగులు:* ${disease}`,
      `*ఖచ్చితత్వం / తీవ్రత:* ${confidence} (${severity})`,
      `*లక్షణాలు:* ${symptomsList}`,
      `*కారణం:* ${cause}`,
      `*సిఫార్సు చేసిన నివారణ చర్యలు (సేంద్రీయ):* ${organic}`,
      `*సిఫార్సు చేసిన మందులు / రసాయన నియంత్రణ:* ${chemical}`,
      `*సురక్షిత వినియోగ సూచనలు:* ${safety}`,
      `*ముఖ్యమైన జాగ్రత్తలు:* ${precautionsList}`,
      `*వాతావరణ హెచ్చరిక:* ${weather}`,
      `*తేదీ & సమయం:* ${dateTimeStr}`,
      ``,
      `ధర్తీ టెక్ - నమ్మకమైన వ్యవసాయ సాంకేతికత`,
      `మరింత సహాయం కొరకు కిసాన్ హెల్ప్‌లైన్: 1800-180-1551`,
    ].join('\n');
  }

  if (lang === 'hi') {
    return [
      `*धरती टेक - फसल रोग निदान रिपोर्ट*`,
      ``,
      `*फसल / पौधा:* ${crop}`,
      `*पहचानी गई बीमारी / समस्या:* ${disease}`,
      `*सटीकता / गंभीरता:* ${confidence} (${severity})`,
      `*लक्षण:* ${symptomsList}`,
      `*संभावित कारण:* ${cause}`,
      `*अनुशंसित उपचार (जैविक):* ${organic}`,
      `*अनुशंसित कीटनाशक / रासायनिक नियंत्रण:* ${chemical}`,
      `*सुरक्षित उपयोग निर्देश:* ${safety}`,
      `*महत्वपूर्ण सावधानियां:* ${precautionsList}`,
      `*मौसम चेतावनी:* ${weather}`,
      `*दिनांक और समय:* ${dateTimeStr}`,
      ``,
      `धरती टेक - बेहतर खेती के लिए भरोसेमंद तकनीक`,
      `किसान कॉल सेंटर सहायता: 1800-180-1551`,
    ].join('\n');
  }

  if (lang === 'kn') {
    return [
      `*ಧರ್ತೀ ಟೆಕ್ - ಬೆಳೆ ರೋಗ ಪತ್ತೆ ವರದಿ*`,
      ``,
      `*ಬೆಳೆ / ಸಸ್ಯ:* ${crop}`,
      `*ಪತ್ತೆಯಾದ ರೋಗ / ಸಮಸ್ಯೆ:* ${disease}`,
      `*ನಿಖರತೆ / ತೀವ್ರತೆ:* ${confidence} (${severity})`,
      `*ಲಕ್ಷಣಗಳು:* ${symptomsList}`,
      `*ಸಾಧ್ಯವಿರುವ ಕಾರಣ:* ${cause}`,
      `*ಶಿಫಾರಸು ಮಾಡಿದ ಚಿಕಿತ್ಸೆ (ಸಾವಯವ):* ${organic}`,
      `*ಶಿಫಾರಸು ಮಾಡಿದ ಕೀಟನಾಶಕ:* ${chemical}`,
      `*ಸುರಕ್ಷಿತ ಬಳಕೆ ಸೂಚನೆಗಳು:* ${safety}`,
      `*ಪ್ರಮುಖ ಮುನ್ನೆಚ್ಚರಿಕೆಗಳು:* ${precautionsList}`,
      `*ಹವಾಮಾನ ಎಚ್ಚರಿಕೆ:* ${weather}`,
      `*ದಿನಾಂಕ ಮತ್ತು ಸಮಯ:* ${dateTimeStr}`,
      ``,
      `ಧರ್ತೀ ಟೆಕ್ - ಉತ್ತಮ ಕೃಷಿಗಾಗಿ ವಿಶ್ವಾಸಾರ್ಹ ತಂತ್ರಜ್ಞಾನ`,
      `ಕಿಸಾನ್ ಸಹಾಯವಾಣಿ: 1800-180-1551`,
    ].join('\n');
  }

  if (lang === 'ta') {
    return [
      `*தார்த்தி டெக் - பயிர் நோய் கண்டறிதல் அறிக்கை*`,
      ``,
      `*பயிர் / செடி:* ${crop}`,
      `*கண்டறியப்பட்ட நோய்:* ${disease}`,
      `*நம்பகத்தன்மை / தீவிரம்:* ${confidence} (${severity})`,
      `*அறிகுறிகள்:* ${symptomsList}`,
      `*சாத்தியமான காரணம்:* ${cause}`,
      `*பரிந்துரைக்கப்பட்ட சிகிச்சை (இயற்கை):* ${organic}`,
      `*பரிந்துரைக்கப்பட்ட பூச்சிக்கொல்லி:* ${chemical}`,
      `*பாதுகாப்பான பயன்பாட்டு வழிமுறைகள்:* ${safety}`,
      `*முக்கிய முன்னெச்சரிக்கைகள்:* ${precautionsList}`,
      `*வானிலை எச்சரிக்கை:* ${weather}`,
      `*தேதி & நேரம்:* ${dateTimeStr}`,
      ``,
      `தார்த்தி டெக் - சிறந்த விவசாயத்திற்கான நம்பகமான தொழில்நுட்பம்`,
      `கிசான் உதவி எண்: 1800-180-1551`,
    ].join('\n');
  }

  if (lang === 'ml') {
    return [
      `*ധാർത്തി ടെക് - വിള രോഗനിർണയ റിപ്പോർട്ട്*`,
      ``,
      `*വിള / ചെടി:* ${crop}`,
      `*കണ്ടെത്തിയ രോഗം:* ${disease}`,
      `*കൃത്യത / തീവ്രത:* ${confidence} (${severity})`,
      `*ലക്ഷണങ്ങൾ:* ${symptomsList}`,
      `*സാധ്യമായ കാരണം:* ${cause}`,
      `*ശുപാർശ ചെയ്യുന്ന ചികിത്സ (ജൈവ):* ${organic}`,
      `*കീടനാശിനി നിയന്ത്രണം:* ${chemical}`,
      `*സുരക്ഷിത ഉപയോഗ നിർദ്ദേശങ്ങൾ:* ${safety}`,
      `*പ്രധാന മുൻകരുതലുകൾ:* ${precautionsList}`,
      `*കാലാവസ്ഥാ മുന്നറിയിപ്പ്:* ${weather}`,
      `*തീയതിയും സമയവും:* ${dateTimeStr}`,
      ``,
      `ധാർത്തി ടെക് - മെച്ചപ്പെട്ട കൃഷിക്കുള്ള വിശ്വസനീയ സാങ്കേതികവിദ്യ`,
      `കിസാൻ ഹെൽപ്പ് ലൈൻ: 1800-180-1551`,
    ].join('\n');
  }

  // Default: English
  return [
    `*DHARTHI TECH - CROP DIAGNOSIS ADVISORY*`,
    ``,
    `*Crop / Plant:* ${crop}`,
    `*Detected Problem:* ${disease}`,
    `*Confidence / Severity:* ${confidence} (${severity})`,
    `*Symptoms:* ${symptomsList}`,
    `*Possible Cause:* ${cause}`,
    `*Recommended Treatment (Organic):* ${organic}`,
    `*Recommended Chemical Control:* ${chemical}`,
    `*Safe Usage Instructions:* ${safety}`,
    `*Important Precautions:* ${precautionsList}`,
    `*Weather Warning:* ${weather}`,
    `*Date & Time:* ${dateTimeStr}`,
    ``,
    `Dharthi Tech – Trusted Technology for Better Farming`,
    `Kisan Helpline: 1800-180-1551`,
  ].join('\n');
}

export function createWhatsAppDeepLink(phone: string, message: string): string {
  const cleanPhone = phone.replace(/\D/g, '').slice(-10);
  const encodedText = encodeURIComponent(message);
  // Official standard wa.me link with country code 91
  return `https://api.whatsapp.com/send?phone=91${cleanPhone}&text=${encodedText}`;
}
